    /// Expands a copy of `byte_len` bytes from `src` to `dst` as an inline
    /// sequence of loads and stores.
    ///
    /// Both `src` and `dst` are raw host addresses of type `pointer_type` which
    /// have already been bounds-checked. The byte range is covered greedily
    /// using the widest available load/store type (`i8x16`, then `i64`, `i32`,
    /// `i16`, and finally `i8`).
    ///
    /// All loads are emitted before any stores so that overlapping source and
    /// destination ranges are copied with `memmove` semantics.
    fn emit_inline_memory_copy(
        &mut self,
        builder: &mut FunctionBuilder<'_>,
        dst: ir::Value,
        src: ir::Value,
        byte_len: u64,
    ) {
        // These accesses have already been bounds-checked so they cannot trap.
        //
        // The endianness is explicitly little-endian: loading and storing with
        // the same type and endianness preserves the exact bit pattern
        // regardless of the target's native byte order, and on big-endian
        // targets (e.g. big-endian Pulley) SIMD (v128) load/store instructions
        // only encode a little-endian variant and would assert if given a
        // big-endian flag.
        let mut flags = ir::MemFlagsData::new();
        flags.set_notrap();
        flags.set_endianness(Endianness::Little);

        // Widest-first list of chunk sizes (in bytes) and their load/store type.
        const CHUNKS: &[(u64, ir::Type)] = &[
            (16, ir::types::I8X16),
            (8, ir::types::I64),
            (4, ir::types::I32),
            (2, ir::types::I16),
            (1, ir::types::I8),
        ];

        // Emit every load first, recording the offset and loaded value, and
        // only then emit the corresponding stores.
        let mut loaded: SmallVec<[(i32, ir::Value); 16]> = SmallVec::new();
        let mut offset: u64 = 0;
        while offset < byte_len {
            let remaining = byte_len - offset;
            let (size, ty) = CHUNKS
                .iter()
                .copied()
                .find(|(size, _)| *size <= remaining)
                .expect("a one-byte chunk always fits");
            let offset32 = i32::try_from(offset).unwrap();
            let value = builder.ins().load(ty, flags, src, offset32);
            loaded.push((offset32, value));
            offset += size;
        }
        for (offset32, value) in loaded {
            builder.ins().store(flags, value, dst, offset32);
        }
    }

