/// Attempts to resolve `val` to a statically-known `i64` constant by looking
/// through the constant-producing and constant-preserving instructions that
/// bulk-copy lengths are built out of (`iconst`, integer width casts, and
/// `imul_imm`/`iadd_imm` by a constant).
///
/// Returns `None` if the value is not a compile-time constant.
fn value_as_const_i64(func: &Function, val: ir::Value) -> Option<i64> {
    let inst = func.dfg.value_def(val).inst()?;
    match func.dfg.insts[inst] {
        ir::InstructionData::UnaryImm {
            opcode: ir::Opcode::Iconst,
            imm,
        } => Some(imm.bits()),
