            let base = value_as_const_i64(func, arg)?;
            match opcode {
                ir::Opcode::ImulImm => base.checked_mul(imm.bits()),
                ir::Opcode::IaddImm => base.checked_add(imm.bits()),
                _ => None,
            }
        }
